mapper.insert:
INSERT INTO model (
name, model_name, provider_id, description, model_type, support_internet, support_reasoning, support_tool,
support_mcp, support_vision, price, status, is_public, active, create_time, update_time
) VALUES (
#{name}, #{modelName}, #{providerId}, #{description}, #{modelType}, #{supportInternet}, #{supportReasoning},
#{supportTool}, #{supportMcp}, #{supportVision}, #{price}, #{status}, #{isPublic}, #{active}, #{createTime},
#{updateTime}
)

mapper.select:
SELECT * FROM model
WHERE active = 1
AND (is_public = 1 OR creator = #{currentUsername})

    AND (name LIKE CONCAT('%', #{name}, '%')
    OR model_name LIKE CONCAT('%', #{name}, '%'))


    AND provider_id = #{providerId}


    AND model_type = #{modelType}


    AND status = #{status}


    AND (


            support_internet = 1
            support_reasoning = 1
            support_tool = 1
            support_mcp = 1
            support_vision = 1


    )


    AND price >= #{minPrice}


    AND price <= #{maxPrice}

ORDER BY status DESC, update_time DESC
